    if(Array.isArray(ly.frames) && ly.frames.length > 1){ let k = 0; el._anim = setInterval(function(){ k = (k + 1) % ly.frames.length; el.src = ly.frames[k]; }, 1000 / Math.max(1, Math.min(30, ly.fps || 8))); }
    mount.appendChild(el); layerEls.push(el);
