  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('width', String(W)); svg.setAttribute('height', String(H));
  svg.style.display = 'block';
  const path = function(a, b, color, dash){
    const x1=px(a),y1=py(a),x2=px(b),y2=py(b),mx=(x1+x2)/2;
    const p = document.createElementNS(NS, 'path');
    p.setAttribute('d', 'M'+x1+','+y1+' C'+mx+','+y1+' '+mx+','+y2+' '+x2+','+y2);
    p.setAttribute('fill', 'none');
    p.setAttribute('stroke', color);
    p.setAttribute('stroke-width', dash ? '1.3' : '1.5');
    if(dash){ p.setAttribute('stroke-dasharray', '4 3'); p.setAttribute('opacity', '0.7'); }
    svg.appendChild(p);
  };
  treeEdges.forEach(function(e){ path(e[0], e[1], '#242938', false); });
  extraEdges.forEach(function(e){ path(e[0], e[1], '#5FD4D4', true); });
